import json
import os
import sys
from typing import Any, Dict, Optional

from google.cloud import pubsub_v1


class DeadLetterPublisher:
    def __init__(
        self,
        dead_letter_topic: Optional[str] = None,
        project_id: Optional[str] = None,
    ) -> None:
        self.project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT")
        self.dead_letter_topic = dead_letter_topic or os.environ.get("DEAD_LETTER_TOPIC")

        if not self.project_id:
            raise ValueError("Missing Google Cloud project ID. Set GOOGLE_CLOUD_PROJECT.")
        if not self.dead_letter_topic:
            raise ValueError("Missing dead-letter topic. Set DEAD_LETTER_TOPIC.")

        self.publisher = pubsub_v1.PublisherClient()
        self.topic_path = self.publisher.topic_path(self.project_id, self.dead_letter_topic)

    def send_failed_message(self, message: Dict[str, Any], error: str, original_topic: Optional[str] = None) -> str:
        payload = {
            "message": message,
            "error": error,
            "original_topic": original_topic,
        }
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        future = self.publisher.publish(
            self.topic_path,
            data,
            content_type="application/json",
            dead_letter_reason=error,
            original_topic=original_topic or "",
        )
        return future.result(timeout=30)

    def close(self) -> None:
        self.publisher.transport.close()


def main() -> None:
    raw = sys.stdin.read().strip()
    if not raw:
        raise ValueError("Expected JSON input on stdin.")

    try:
        message = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ValueError("Input must be valid JSON.") from exc

    error = os.environ.get("FAILED_MESSAGE_ERROR", "processing_failed")
    original_topic = os.environ.get("ORIGINAL_TOPIC")

    publisher = DeadLetterPublisher()
    try:
        message_id = publisher.send_failed_message(message, error=error, original_topic=original_topic)
        sys.stdout.write(message_id)
    finally:
        publisher.close()


if __name__ == "__main__":
    main()
